"""Generate current findings only from completed, identified measured cohorts."""
import hashlib
import json
from pathlib import Path
import statistics

ROOT=Path(__file__).resolve().parents[1]
EXP=ROOT.parent
OUT=EXP/'results'

def main():
    names=['browser-checks','native-checks','browser-cpu','native-cpu','browser-autopilot','native-autopilot','sizes','simulation-tests','shader-metadata-tests','shader-contract','native-services','package-smoke','libwgf-context','service-checks','native-audio-device','reference-features']
    data={name:json.loads((OUT/(name+'.json')).read_text()) for name in names}
    assert data['simulation-tests']['passed'] and data['simulation-tests']['checks']>=30
    assert data['shader-metadata-tests']['passed'] and data['native-services']['passed'] and data['package-smoke']['passed']
    service=data['service-checks']
    for target in ['browser','native']:
        value=service[target]
        assert value['passed'] and len(value['runs'])==2 and all(run['passed'] for run in value['runs'])
        assert not value['runs'][0]['persisted'] and value['runs'][1]['persisted']
        assert value['singleDownloadStoredAudio'] and all(value['requests']['/assets/fixture.'+format]==1 for format in ['wav','ogg','opus'])
        assert value['peakConcurrentTransfers']==2
    assert data['native-audio-device']['passed'] and data['native-audio-device']['callbacks']>0
    assert service['audioFormats']==['PCM16 WAV','Ogg/Vorbis','Ogg/Opus'] and service['native']['decoder']=='libsndfile-1.2.2'
    for result in [service,data['native-services'],data['native-audio-device']]:
        for source,identity in result['sources'].items():
            assert hashlib.sha256((ROOT/source).read_bytes()).hexdigest()==identity,source
    for name in names[:6]:assert data[name]['completed'],name
    sizes=data['sizes'];bc=data['browser-checks'];nc=data['native-checks'];bw=data['browser-cpu'];nw=data['native-cpu'];bp=data['browser-autopilot'];np=data['native-autopilot']
    assert len(bc['checks'])==len(nc['checks'])==5 and len(bw['runs'])==len(nw['runs'])==3
    for file in sizes['files']+sizes['optionalFiles']:
        assert bc['artifacts'][file['file']]==bw['artifacts'][file['file']]==bp['artifacts'][file['file']]==file['sha256']
    assert nc['sha256']==nw['sha256']==np['sha256']==sizes['native']['sha256']
    assert all(c['difference']['maxRgbDifference']==0 for c in nc['checks'])
    for browser,native in zip(bc['checks'],nc['checks']):
        assert browser['tick']==native['tick']
        assert browser['result']['game']==native['result']['game']
        assert browser['result']['geometryHash']==native['result']['geometryHash']
    assert bp['result']['game']==np['result']['game'] and bp['result']['autopilot']==np['result']['autopilot']
    assert bp['script']==np['script'] and np['difference']['maxRgbDifference']==0
    assert all(r['game']==bw['runs'][0]['game'] for r in bw['runs']+nw['runs'])
    display=json.loads((OUT/'display-control.json').read_text());assert display['restored'] and display['before']==display['after']
    summary={'browser':{},'native':{},'sources':{name:hashlib.sha256((OUT/(name+'.json')).read_bytes()).hexdigest() for name in names}}
    previous=json.loads((OUT/'stages/05-services-cohort/sizes.json').read_text())
    stages=[json.loads((OUT/'stages'/file).read_text()) for file in ['01-shader-reflection-sizes.json','02-interfaces-sizes.json','03-expanded-sizes.json']]+[previous,sizes]
    text=['# Hybrid Asteroids findings','',
          '**One shared Haxe game and renderer runs through separate graphics, input, audio, fetch, storage, asset and host contracts. Browser WebGL2 and Linux hxcpp/Sokol ran, with zero browser Wasm and zero target conditionals in framework/game sources. Persistent encoded storage and typed audio resource/playback lifetimes now run on both targets. Full libwgf feature equivalence and a performance advantage remain unproven.**','',
          '## What changed and ran','',
          'Reusable contracts/utilities live in prototype/framework/hybrid; Asteroids lives in prototype/src. Each target supplies graphics/input/audio/fetch/storage adapters; shared AssetService and AudioResources own cache/loading/lifetime policy. IHost composes services and owns window/loop/clock/focus; IDiagnostics separates experiment probes/capture. Input preserves edges until a simulation tick consumes them. Native uses Sokol app/graphics/audio with a Linux evdev gamepad prototype; current native binaries have no SDL dependency.','',
          'The playable slice has a drifting title field, focusable/clickable menu buttons, game over/restart/return to title, ship life icons, session best, extra lives every 10000 points, six-bullet cap, 90-tick wave delay, 120-tick respawn delay and invulnerability, varied rocks, thrust/explosion particles, eight original sound files and looping thrust audio. The logical playfield is now 960×720. Bitmap text, quantized motion/collision/wrap behavior, art and sound waveforms differ from libwgf; there is no general ECS/prefab/UI framework.','',
          f"{data['simulation-tests']['checks']} shared interpreter assertions cover game rules, menu hit testing, input, WAV validation and autopilot. {data['shader-metadata-tests']['checks']} shader metadata checks pass. An independent framework consumer compiled under interpreter and JS/Node with no game/adapters/generated-shader classpaths. Native service checks passed {data['native-services']['checks']} assertions covering pipe-fed evdev records, PCM mixing, resampling, concurrency, pause, bounded stream queues, underruns and EOF. A real Sokol/ALSA device delivered {data['native-audio-device']['callbacks']} silent callbacks. Physical controllers and audible output quality remain untested.",'',
          f"The same Haxe async service suite passed browser runs of {[run['checks'] for run in service['browser']['runs']]} checks and native runs of {[run['checks'] for run in service['native']['runs']]} checks (progress callback counts may vary). An isolated HTTP fixture verifies response/status, byte progress, overflow, timeout, exactly-once cancellation, shutdown/late completion, at most two concurrent transfers, committed read/write/remove, path validation and persistence across pages/processes. Each target fetched each WAV, Vorbis and Opus fixture exactly once across both runs: ensure, cache reads, decoded clips and stored streaming reuse encoded bytes. Browser uncached streams of all three formats play remotely and leave the store empty; native remote streams fail explicitly. The stereo 48 kHz Opus fixture exercises downmix/rate normalization. Pause/resume, loops, resource/source leases, stop, natural EOF, empty/malformed input and decode cancellation pass. These are signal/duration/lifecycle checks, not audible-quality, bit-identical codec output, playback before network EOF, or sustained large-file frame-time evidence.",'',
          'Browser game checks exercised actual DOM pointer/keyboard events, short taps, resize, focus pause/resume, high-DPI pointer mapping, an injected standard Gamepad fixture/disconnect, sound loops, graphics validation and missing-sound HTTP404 failure text. Native checks exercised actual X11 pointer/keyboard/resize and loop stopping with real Sokol/ALSA callbacks. Native OS suspend/resume and physical controllers remain untested.','',
          'Five frozen replay points (0,180,600,1200,2400) match game state, prepared float32 vertex bytes and RGB pixels exactly. One draw per frame, reported upload bytes, no GL errors. Fractional text scaling initially exposed texel-boundary rounding differences between the GPUs; a common 0.01-texel glyph UV bias avoids ties. Capture/audit checks run separately from CPU sampling.','',
          f"The same packaged JSON autopilot completed on both rendered targets in {bp['result']['autopilot']['ticks']} simulated ticks, with identical outcomes and final state/pixels: title → play → fire/thrust → game over → title → restart. Fast mode executes up to 120 fixed ticks per delivered frame and establishes correctness, not real-time performance. Commands are bounded press/hold/wait/assert operations through IInput, with explicit probe callbacks; no source scraping or direct game-state mutation. Script errors/timeouts fail the run.",'',
          'Shader source and bindings remain generated by pinned sokol-shdc. bare_yaml is parsed with pinned PyYAML SafeLoader plus duplicate-key rejection and strict schema/layout validation. One explicit CPU packing schema generates Haxe inline offsets and native layout/binding constants; shader reflection has no runtime parser. Autopilot separately uses ordinary Haxe Reflect to validate structured JSON fields; it does not reflect over shader or game internals.','',
          '## Delivery and growth','',
          '| Stage | Code + HTML gzip KiB | Code + HTML Brotli KiB | Sound gzip KiB | Whole play delivery gzip KiB |','| --- | ---: | ---: | ---: | ---: |']
    for label,stage in zip(['Shader reflection / original slice','Interface/service extraction / original rules','Expanded game + assets + autopilot (SDL2 cohort)','Fetch/cache + WAV clip lifetimes (Sokol cohort)','Ogg codecs + Vorbis game delivery (Sokol cohort)'],stages):
        code=stage.get('codeTotal',stage['total']);sound=stage.get('soundTotal',{'gzipBytes':0})
        text.append(f"| {label} | {code['gzipBytes']/1024:.2f} | {code['brotliBytes']/1024:.2f} | {sound['gzipBytes']/1024:.2f} | {stage['total']['gzipBytes']/1024:.2f} |")
    text+=['','The extraction stage includes edge/pointer/controller input and reusable clip playback, so its increment includes exercised capability. Intermediate sizes, source identities and correctness cohorts are retained in results/stages. These are sequential feature stages, not same-feature architectural comparisons. Stream creation APIs execute in separate service fixtures; full Haxe DCE removes unused loadStream/createStream/streamSource paths from this Asteroids delivery. Its size is not the cost of shipping every available framework capability.','',
          '| Delivered file | Raw B | Gzip B | Brotli B |','| --- | ---: | ---: | ---: | ---: |']
    for file in sizes['files']:text.append(f"| {file['file']} | {file['rawBytes']:,} | {file['gzipBytes']:,} | {file['brotliBytes']:,} |")
    s=sizes['total'];text += [f"| **Whole play delivery** | **{s['rawBytes']:,}** | **{s['gzipBytes']:,}** | **{s['brotliBytes']:,}** |",'',
          f"Optional autopilot JSON/assets manifest: another {sizes['optionalTotal']['rawBytes']:,} B raw / {sizes['optionalTotal']['gzipBytes']:,} B gzip / {sizes['optionalTotal']['brotliBytes']:,} B Brotli. They are reported separately; normal play requests eight sounds, HTML and JS. All staged files/hashes are retained in sizes.json. No separately downloaded art/font. Wasm: **0 B**.",'',
          f"Same per-file gzip9/mtime0 and Brotli11. Compressed sizes assume server content encoding; local tests serve raw files. Re-encoding the same eight original offline WAV sources as quality 3 Vorbis reduced whole-play gzip from {previous['total']['gzipBytes']/1024:.2f} to {sizes['total']['gzipBytes']/1024:.2f} KiB ({(1-sizes['total']['gzipBytes']/previous['total']['gzipBytes'])*100:.1f}% smaller). Code+HTML grew by {sizes['codeTotal']['gzipBytes']-previous['codeTotal']['gzipBytes']:,} gzip bytes; sound delivery fell from {previous['soundTotal']['gzipBytes']/1024:.2f} to {sizes['soundTotal']['gzipBytes']/1024:.2f} KiB. This is a lossy-codec feature stage, not bit-identical audio or a matched architectural comparison. FFmpeg and parameters are retained in sizes.json; repeated generation produced identical hashes on this toolchain.",'',
          'Browser clips use decodeAudioData, with owned input bytes and PCM normalization; streams use media elements and stored Blob URLs or remote URLs, entirely outside Wasm. Native uses a thin libsndfile 1.2.2 bridge for Vorbis/Opus beneath Sokol PCM delivery. Both accept mono/stereo Ogg clips and normalize to mono 44.1 kHz; native stored Ogg streams decode in bounded chunks. Canonical mono PCM16 WAV remains supported. Stereo output, MP3/general WAV support and native network streaming are not implemented. Codec output need not match bit for bit across platforms.','',
          f"Native executable: {sizes['native']['rawBytes']:,} B, unstripped; external assets and dynamic libsndfile/codec, ALSA/GL/X11/runtime/driver libraries excluded. The system libsndfile build brings transitive codec dependencies; the complete ldd inventory is in sizes.json, rather than attributing all native cost to the executable. SDK/header version/license and hashes are pinned; see README.md. Native packaging remains future work. The hxcpp HTTP/TLS implementation contributes native code; local HTTP does not establish HTTPS interoperability. CPU and GPU each reserve a 2 MiB vertex buffer; audio/device/cache/runtime allocations are additional. Native streams use 8192 float samples per active playback; host-thread stalls can cause underruns after the queued audio drains. Sustained memory/GC has not been profiled.",'',
          '## Runtime observations','',
          '| Target | CPU mean / p95 ms | Simulation mean ms | Render mean ms | FPS range | Worst >25 ms | Ready / first submission ms |','| --- | --- | ---: | ---: | --- | ---: | --- |']
    for target,cohort in [('browser',bw),('native',nw)]:
        runs=cohort['runs'];m=lambda field:statistics.median(field(r) for r in runs)
        value={'meanCpuMs':m(lambda r:r['phases']['cpu']['meanMs']),'p95CpuMs':m(lambda r:r['phases']['cpu']['p95Ms']),'simulationMs':m(lambda r:r['phases']['simulation']['meanMs']),'renderMs':m(lambda r:r['phases']['render']['meanMs']),'fpsRange':[min(r['fps'] for r in runs),max(r['fps'] for r in runs)],'worstLatePercent':max(r['latePercent'] for r in runs),'readyMs':m(lambda r:r['startupMs']),'firstSubmissionMs':m(lambda r:r['firstSubmissionMs'])};summary[target]=value
        text.append(f"| {target} | {value['meanCpuMs']:.3f} / {value['p95CpuMs']:.3f} | {value['simulationMs']:.3f} | {value['renderMs']:.3f} | {value['fpsRange'][0]:.2f}–{value['fpsRange'][1]:.2f} | {value['worstLatePercent']:.3f}% | {value['readyMs']:.2f} / {value['firstSubmissionMs']:.2f} |")
    final=bw['runs'][0]
    text+=['',
          'Three sequential trials per target; 60 warmup +600 measured frames; seed 12345 and 660 replay ticks. Medians of trial means/p95s; all trials retained. Audio delivery disabled, device initialization retained. CPU includes game update, geometry preparation, uploads/submission; service polling (fetch/storage/audio/input), native presentation and cleanup lie outside that clock. These CPU numbers do not measure active download/stream servicing. Driver blocking inside calls is included. No GPU-completion or GC profiling. Live play uses fixed 60 Hz, a 100 ms interval cap and at most 6 catch-up steps; benchmark replay advances once per delivered frame.','',
          f"Final replay: {final['vertices']} vertices / {final['uploadBytes']:,} B upload / one draw; score {final['game']['score']}, hits {final['game']['hits']}, deaths {final['game']['deaths']}. Every trial's final game state matches across targets. This is a game-sized batch, not a capacity/state-changing throughput test.",'',
          f"Host: {bw['cpu']}; Chromium {bw['browser']}; browser {final['host']['renderer']}; native {nw['runs'][0]['host']['renderer']}. No requested CPU throttling. Exact screen saver/DPMS/monitor restoration is verified in display-control.json.",'',
          'Startup clocks begin at the Haxe constructor. Ready includes ensuring/decoding all eight audio assets; first submission may be a loading frame before readiness. Browser excludes initial HTML/JS transfer/evaluation and uses a local server with a fresh browser page context; native includes window/context/device creation and can reuse its persistent file cache from prior checks. These are not matched cold-network/cache or first-presentation measurements.','',
          '## Comparison and package direction','']
    ref=data['libwgf-context'];program=ref['program'];gz=sum(program[k]['gz'] for k in ['js','wasm']);br=sum(program[k]['br'] for k in ['js','wasm'])
    text += [f"Recorded libwgf context: {gz/1024:.1f} KiB gzip / {br/1024:.1f} KiB Brotli for Asteroids code (commit {ref['commit']}), excluding page/assets. Its frame row uses CPU throttling 4x, Chrome tracing and a different playthrough; ours is unthrottled application-clock sampling. No speedup or exact whole-game savings claim is supported. See results/libwgf-context.json.",'',
          'The slice covers representative gameplay/menu/input/audio but differs in font, art, quantized simulation, collision/wrap and scene/UI infrastructure. There is no imported libwgf implementation. [FEATURE_PARITY.md](FEATURE_PARITY.md) compares declared reference capabilities, current executed scope and prioritized interface/performance probes; results/reference-features.json inventories 522 wgrender-c and 834 libwgf public functions at separate current reference snapshots. A full semantic 1:1 mapping and matched workload coverage do not exist. Portable interfaces/utilities can become a haxelib; native still needs thin adapters and shader/CMake/hxcpp integration. Publication, dependency licensing/bundling, installed-backend consumption and API stability remain future work. See [PACKAGING.md](PACKAGING.md).','',
          'HXML owns compiler/classpath choices. hybrid.py runs build/test/services/features/check/autopilot/serve/measure/sizes/report with argument lists; Run.hx optionally delegates. Tooling contributes no shipped runtime bytes. JSON autopilot can be reused with another app’s probes.','',
          '| Source group | Nonblank physical lines | Target conditionals |','| --- | ---: | ---: |']
    for group,value in sizes['sourceSplit'].items():text.append(f"| {group} | {value['nonblankPhysicalLines']} | {value['targetConditionals']} |")
    text+=['','Counts include comments/compact statements and exclude generated code/tooling/tests; inventory, not an effort estimate. C include guards remain adapter-only.','',
          '## Recommendation and remaining gates','',
          'Proceed with the Haxe-owned framework and independently selected services/backends. Ogg closes the compressed-audio delivery gate without browser Wasm. Next, exercise mixed state-changing submissions, UI/clipping and multipass rendering, then a loading lit Racer scene with representative textures/models and the agreed optional physics module. Measure code growth, memory and whole-host frames at each step; extend to Wits animation/scene breadth afterward. FEATURE_PARITY.md specifies the probes and reference gaps. Native graphics needs an executed modern backend with the same renderer/shader. Desktop performance matters more than native binary size. SDL3 remains a candidate for graphics/window/input/gamepads/audio; it has not been implemented or benchmarked. Retain Sokol as the executed baseline and run a matched SDL3 comparison before choosing.','',
          'The fetch/cache prototype bounds whole-file operations at 8 MiB, with two fetch/storage workers/transfers per adapter and cooperative 2 ms work queues. Ogg clips cap normalized PCM at 8 MiB; browser decoding can allocate before this check, so it is not a decoder memory guarantee. Native clip decoding has two workers; native stream fills run on the host, and disk/codec calls may exceed the nominal per-stream slice. No content-version manifest, revalidation, eviction/quota policy, concurrent ensure deduplication, resumable/direct-to-storage large downloads or play-and-store path. Native cancellation suppresses callbacks but does not interrupt blocking HTTP/disk/codec work or undo committed writes; socket timeout differs from the browser deadline, redirects are not normalized, and HTTPS has not run. Native streams support stored canonical WAV/Vorbis/Opus, with remote network streaming deferred. See INTERFACE.md for exact semantics.','',
          'Browser WebGPU, Windows/macOS/mobile, physical controllers/audible output, general UI/ECS/prefab, context/device recovery, broader lifecycle testing, sustained allocation/GC/memory and matched libwgf workload/cold-start measurement remain unproven. A tested Haxe source boundary does not establish a production-ready package.','',
          'Reproduction and versions: [README.md](README.md). Interfaces: [INTERFACE.md](INTERFACE.md). Tool/package rationale: [PACKAGING.md](PACKAGING.md). Raw identified evidence: [results/](results/). Regenerate using hybrid.py report.']
    (OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(EXP/'FINDINGS.md').write_text('\n'.join(text)+'\n');print(json.dumps(summary))

if __name__=='__main__':main()
